          gTasks[taskId].tFollowUpTaskPtrLo = (Swap_Task_HandleChooseMons);
          gTasks[taskId].tFollowUpTaskState = STATE_CHOOSE_MONS_HANDLE_INPUT;
          gTasks[taskId].func = Swap_Task_ScreenInfoTransitionIn;
